def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    colors={v for row in grid for v in row}
    marker=max(colors)  # each task uses the higher of the two input colors
    bg=min(colors)
    for r in range(h):
        pts=[c for c,v in enumerate(grid[r]) if v==marker]
        for a,b in zip(pts,pts[1:]):
            for c in range(a+1,b): out[r][c]=3
    for c in range(w):
        pts=[r for r in range(h) if grid[r][c]==marker]
        for a,b in zip(pts,pts[1:]):
            for r in range(a+1,b): out[r][c]=3
    return out
